CustomField.formula:
IF(TEXT(Case__r.Type)='Inquiry','Customer Care',
IF(TEXT(Case__r.Type)='Request POS' && (TEXT(Case__r.Case_Type__c)='Request_POS_Redemption' || TEXT(Case__r.Case_Type__c)='Request_POS_Surrender_Non_UL' || TEXT(Case__r.Case_Type__c)='Request_POS_Surrender Endowment' || TEXT(Case__r.Case_Type__c)='Request_POS_Withdrawal'),'Pelayanan Polis',
IF(TEXT(Case__r.Type)='Complaint','Pengaduan Nasabah',
IF( ((TEXT(Case__r.Type)='Request' && Case__r.MOT__c='I Claim') || TEXT(MOT__c) == 'I Claim') && TEXT(Claim_Transaction_Type__c)='Cashless','Klaim Penjaminan',
IF( ((TEXT(Case__r.Type)='Request' && Case__r.MOT__c='I Claim') || TEXT(MOT__c) == 'I Claim') && (TEXT(Claim_Transaction_Type__c)='Reimbursement' || TEXT(Claim_Transaction_Type__c)=''),'Klaim Penggantian','')
)
)
)
)
